INSERT INTO "stock_take_policies" OVERRIDING SYSTEM VALUE ("id", "key", "value", "description", "updated_by", "updated_at", "created_at") VALUES (1, 'stock_take.require_approval', 'false', 'When true, counting sessions must be submitted and approved before they can be posted.', NULL, '2026-07-30 17:06:06', '2026-07-30 17:06:06');
INSERT INTO "stock_take_policies" OVERRIDING SYSTEM VALUE ("id", "key", "value", "description", "updated_by", "updated_at", "created_at") VALUES (2, 'stock_take.auto_approve_below_value', '0', 'When require_approval=true, sessions whose total |gain|+|loss| value is strictly below this threshold are auto-approved inline at post time (actor = system). 0 disables auto-approval.', NULL, '2026-07-30 17:06:06', '2026-07-30 17:06:06');
INSERT INTO "stock_take_policies" OVERRIDING SYSTEM VALUE ("id", "key", "value", "description", "updated_by", "updated_at", "created_at") VALUES (3, 'stock_take.approver_roles', '["admin", "manager"]', 'Roles permitted to approve a submitted stock-take session. Order is irrelevant. Default: admin, manager.', NULL, '2026-07-30 17:06:06', '2026-07-30 17:06:06');
INSERT INTO "stock_take_policies" OVERRIDING SYSTEM VALUE ("id", "key", "value", "description", "updated_by", "updated_at", "created_at") VALUES (4, 'stock_take.variance_threshold_block', '0', 'When require_approval=false, sessions whose total |gain|+|loss| value is ≥ this threshold are STILL forced through approval. 0 disables the threshold (no force-approve).', NULL, '2026-07-30 17:06:06', '2026-07-30 17:06:06');
INSERT INTO "stock_take_policies" OVERRIDING SYSTEM VALUE ("id", "key", "value", "description", "updated_by", "updated_at", "created_at") VALUES (5, 'stock_take.abc_threshold_a', '0.8', 'ABC classification: cumulative usage-value share (0–1) for class A. Products whose cumulative usage value falls at or below this share of the warehouse total are class A. Default 0.80 (top 80% of value).', NULL, '2026-07-30 17:06:06', '2026-07-30 17:06:06');
INSERT INTO "stock_take_policies" OVERRIDING SYSTEM VALUE ("id", "key", "value", "description", "updated_by", "updated_at", "created_at") VALUES (6, 'stock_take.abc_threshold_b', '0.95', 'ABC classification: cumulative usage-value share (0–1) for classes A+B. Products above the A threshold but at or below this share are class B; the rest are C. Default 0.95 (B spans 80%–95%, C is the bottom 5%).', NULL, '2026-07-30 17:06:06', '2026-07-30 17:06:06');
INSERT INTO "stock_take_policies" OVERRIDING SYSTEM VALUE ("id", "key", "value", "description", "updated_by", "updated_at", "created_at") VALUES (7, 'stock_take.abc_lookback_days', '365', 'ABC classification: lookback window in days for computing annual usage value from stock_transactions (outbound consumption). Default 365 (one year).', NULL, '2026-07-30 17:06:06', '2026-07-30 17:06:06');
INSERT INTO "stock_take_policies" OVERRIDING SYSTEM VALUE ("id", "key", "value", "description", "updated_by", "updated_at", "created_at") VALUES (8, 'stock_take.recount_reset_to_system', 'false', 'Phase 7: when true, recountWarehouse() resets physical_qty to system_qty on every line (counter starts fresh). When false (default), the previous physical_qty is preserved so the counter sees the prior count and adjusts. The pre-recount values are always captured in the recount audit row regardless.', NULL, '2026-07-30 17:06:06', '2026-07-30 17:06:06');
INSERT INTO "stock_take_policies" OVERRIDING SYSTEM VALUE ("id", "key", "value", "description", "updated_by", "updated_at", "created_at") VALUES (9, 'stock_take.revaluation_epsilon', '0.01', 'Phase 9: minimum |post_rate - system_rate| delta (in currency units) that triggers a revaluation adjusting entry at post time. When the avg cost drifts by more than this epsilon between setup and post, an additional Dr/Cr Inventory/Inventory Revaluation Expense line is posted for (post_rate - system_rate) * physical_qty. Default 0.01 (any non-trivial drift). Set to 0 to revalue on every post.', NULL, '2026-07-30 17:06:06', '2026-07-30 17:06:06');
INSERT INTO "stock_take_policies" OVERRIDING SYSTEM VALUE ("id", "key", "value", "description", "updated_by", "updated_at", "created_at") VALUES (10, 'stock_take.max_reopens', '1', 'Phase 10: maximum number of times a reversed stock-take session can be re-opened for correction + re-posting. Default 1 (one re-open per session — prevents endless re-open/re-post churn). Set to 0 to forbid re-opening entirely (reversed = hard terminal). Set to a higher number for environments that allow iterative correction. The cap is enforced by StockTakeService::reOpen, which throws when re_open_count >= max_reopens.', NULL, '2026-07-30 17:06:06', '2026-07-30 17:06:06');
